sys_variable_value.value:
(function execute(inputs, outputs) {
var profile = gs.getProperty("x_vuram_financia_0.fcc_entity_profile_change");
var screening = gs.getProperty("x_vuram_financia_0.fcc_entity_screening_change");
var profilefield = gs.getProperty("x_vuram_financia_0.fcc_entity_profile_change_fields");
var screeningfield = gs.getProperty("x_vuram_financia_0.fcc_entity_screening_change_fields");
var mergedfields;

if(profile == "true")
{
	mergedfields = [profilefield,mergedfields].join(', ');
}

if(screening == "true")
{
	mergedfields = [screeningfield,mergedfields].join(', ');
}


var change = inputs.changefields;
var array = [];
for(x in change){

    array.push(change[x].field_name);
 }
 function getCommonElements(arr1, arr2) {
    return arr1.filter(item => arr2.includes(item));
}


var common = getCommonElements(array, mergedfields);
outputs.output = common;
//gs.info('array: ' + array);
//gs.info('Common elements: ' + profile);

//gs.info("@12345678"+JSON.stringify(inputs.changefields));
})(inputs, outputs);

